/*
 * targeting.c -- rendezvous targeting against the real AGC code (yaAGC).
 *
 * Inputs and expected words: tools/oracle/cases/targeting.spec / .txt
 * (Comanche055), generated by tools/oracle/cases/gen/gen_targeting.py.
 * INITVEL (conic, earth and moon, and one precision iteration through
 * INTEGRVS), CDHMVR (the CDH maneuver of P32/P33) and S34/35.2 (the TPI
 * required velocity: INTINT, ACTCENT, INITVEL, LOMAT -> DELVLVC).
 *
 * Tolerances (LSB of the AGC word): see docs/modules/oracle-cases.md.
 */
#include <stdio.h>

#include "agc/core/assert.h"
#include "agc/core/flags_common.h"
#include "agc/core/interp.h"
#include "agc/core/state.h"
#include "agc/exec/exec.h"
#include "agc/nav/auxiliary.h"
#include "agc/nav/integration.h"
#include "agc/programs/rendezvous.h"
#include "oracle_txt.h"

bool agc_assert_report(const char *file, int line, const char *expr)
{
    (void) printf("assert %s:%d %s\n", file, line, expr);

    return (false);
}

static agc_rendz_t *fresh(const char *t)
{
    agc_navaux_padload_t pad = {0};
    const bool           moon = oracle_in(t, "RTX1", 0) == -10;

    agc_state_init(AGC_VEHICLE_CSM);
    (void) agc_exec_init();
    (void) agc_waitlist_init();
    (void) agc_navaux_set_padload(&pad);
    (void) agc_integ_ctx_init(agc_integ_shared_ctx());
    agc_rendz_t *rz = agc_rendz_erasable();

    agc_rendz_reset(rz);
    agc_flag_put(AGC_FLAG_CMOONFLG, moon);
    agc_flag_put(AGC_FLAG_MOONFLAG, moon);
    (void) agc_rendz_selectmu(rz, moon);

    return (rz);
}

static void initvel(const char *t, long tol)
{
    agc_interp_t ip;
    agc_rendz_t *rz = fresh(t);

    agc_interp_init(&ip);
    rz->rinit  = oracle_in_vec(t, "RINIT");
    rz->vinit  = oracle_in_vec(t, "VINIT");
    rz->rtarg  = oracle_in_vec(t, "RTARG");
    rz->dellt4 = oracle_in_dp(t, "DELLT4", 0);
    rz->intime = oracle_in_dp(t, "INTIME", 0);
    const agc_status_t st =
        agc_rendz_initvel(&ip, rz, (agc_sp_t) oracle_in(t, "VAC1", 0),
                          oracle_in_dp(t, "VAC1+2", 0), AGC_JOB_NONE);

    oracle_require_ok(t, "POODOO");
    (void) oracle_cmp(t, "status", st, AGC_STATUS_OK, 0);
    oracle_cmp_vec(t, "RTARG", rz->rtarg, oracle_out_vec(t, "RTARG"), tol);
    oracle_cmp_vec(t, "VIPRIME", rz->viprime, oracle_out_vec(t, "VIPRIME"),
                   tol);
    oracle_cmp_vec(t, "VTPRIME", rz->vtprime, oracle_out_vec(t, "VTPRIME"),
                   tol);
    oracle_cmp_vec(t, "DELVEET3", rz->delveet3, oracle_out_vec(t, "DELVEET3"),
                   tol);
}

static void cdh(const char *t, long tol)
{
    agc_interp_t ip;
    agc_rendz_t *rz = fresh(t);

    agc_interp_init(&ip);
    rz->ract2  = oracle_in_vec(t, "RACT2");
    rz->vact2  = oracle_in_vec(t, "VACT2");
    rz->rpass2 = oracle_in_vec(t, "RPASS2");
    rz->vpass2 = oracle_in_vec(t, "VPASS2");
    rz->up1    = oracle_in_vec(t, "UP1");
    (void) agc_rendz_cdhmvr(&ip, rz);
    oracle_require_ok(t, "POODOO");
    /* F13: DIFFALT 31 LSB (62 m) off for an exactly circular passive
     * orbit (the AGC gets the exact 100 km): TIMETHET's RNEW in C.      */
    (void) oracle_cmp(t, "DIFFALT", rz->diffalt, oracle_out_dp(t, "DIFFALT"),
                      64);
    oracle_cmp_vec(t, "VACT3", rz->vact3, oracle_out_vec(t, "VACT3"), tol);
    oracle_cmp_vec(t, "DELVEET2", rz->delveet2, oracle_out_vec(t, "DELVEET2"),
                   tol);
}

static void tpi(const char *t, long tol)
{
    agc_interp_t ip;
    agc_rendz_t *rz = fresh(t);

    agc_interp_init(&ip);
    rz->ract3  = oracle_in_vec(t, "RACT3");
    rz->vact3  = oracle_in_vec(t, "VACT3");
    rz->rpass3 = oracle_in_vec(t, "RPASS3");
    rz->vpass3 = oracle_in_vec(t, "VPASS3");
    rz->unrm   = oracle_in_vec(t, "UNRM");
    rz->intime = oracle_in_dp(t, "INTIME", 0);
    rz->tpass4 = oracle_in_dp(t, "TPASS4", 0);
    rz->nn     = 0;
    const agc_status_t st =
        agc_rendz_tpi_required_velocity(&ip, rz, AGC_JOB_STATINT1);

    oracle_require_ok(t, "POODOO");
    (void) oracle_cmp(t, "status", st, AGC_STATUS_OK, 0);
    oracle_cmp_vec(t, "RTARG", rz->rtarg, oracle_out_vec(t, "RTARG"), tol);
    oracle_cmp_vec(t, "VPASS4", rz->vpass4, oracle_out_vec(t, "VPASS4"), tol);
    (void) oracle_cmp(t, "ACTCENT", rz->actcent, oracle_out_dp(t, "ACTCENT"),
                      tol);
    (void) oracle_cmp(t, "DELLT4", rz->dellt4, oracle_out_dp(t, "DELLT4"), 0);
    oracle_cmp_vec(t, "VIPRIME", rz->viprime, oracle_out_vec(t, "VIPRIME"),
                   tol);
    oracle_cmp_vec(t, "VTPRIME", rz->vtprime, oracle_out_vec(t, "VTPRIME"),
                   tol);
    oracle_cmp_vec(t, "DELVEET3", rz->delveet3, oracle_out_vec(t, "DELVEET3"),
                   tol);
    oracle_cmp_vec(t, "DELVLVC", rz->delvlvc, oracle_out_vec(t, "DELVLVC"),
                   tol);
}

int main(void)
{
    if (!oracle_load("targeting"))
    {
        (void) printf("oracle_targeting: SKIP (case files not found)\n");

        return (0);
    }

    initvel("initvel_earth", 0);
    initvel("initvel_earth_far", 0);
    initvel("initvel_moon", 64);
    initvel("initvel_earth_prec", 4096); /* DV bug, integration */
    cdh("cdh_earth", 1024);
    cdh("cdh_earth_ell", 1024);
    tpi("tpi_earth", 1024);
    tpi("tpi_earth_b", 1024);

    return (oracle_finish("oracle_targeting"));
}
